-- Team dock (team_dock_formation_menu): the 3D model of the selected player (UpdateViewChara3DModel, «Ver apariencia»
-- InitChara3DModelByUniformNoWindow) wears the outfit he has in the «Atuendo» slot ([[VRFW.Outfit]] of a mod,
-- VR-Framework CMND_VRFW_OUTFIT_OF) instead of the team kit. Only the look command of that model (0xC4232044 on
-- team02_01_attach_formation_frame) is changed, once per call, while the retail function runs: the wrappers swap
-- funcLuaMenuCommand for the call and put it back (as the form viewer does); coach (16) / manager (32) looks are
-- untouched. No outfit worn, nothing declared, an older framework (pcall fails): retail. Globals only (no chunk
-- local is read); nothing runs at load time.
do
  VRFW_Outfit = VRFW_Outfit or {}
  VRFW_Outfit.OF = 3184750648
  VRFW_Outfit.LOOK = 3290636356                     -- 0xC4232044 (layer, idx, uniform, number, flags, entry, shoes)
  VRFW_Outfit.LAYER = 189137238                     -- team02_01_attach_formation_frame

  function VRFW_Outfit.Of(h)
    if type(h) ~= "number" or h == 0 then
      return 0, 0
    end
    local ok, item, u = pcall(funcLuaCommand, VRFW_Outfit.OF, h)
    if not ok or type(item) ~= "number" or type(u) ~= "number" then
      return 0, 0
    end
    return item, u
  end

  -- run fn(...) with the dock model's look command dressed in uniform u (once)
  function VRFW_Outfit.Dressed(u, fn, ...)
    local real = funcLuaMenuCommand
    local done = false
    local hook
    hook = function(id, layer, idx, uniform, number, flags, ...)
      if not done and id == VRFW_Outfit.LOOK and layer == VRFW_Outfit.LAYER then
        done = true
        if flags ~= 16 and flags ~= 32 then
          uniform = u
        end
      end
      return real(id, layer, idx, uniform, number, flags, ...)
    end
    funcLuaMenuCommand = hook
    local r1, r2, r3 = fn(...)
    if funcLuaMenuCommand == hook then
      funcLuaMenuCommand = real
    end
    return r1, r2, r3
  end

  if VRFW_Outfit.PrevView == nil then
    VRFW_Outfit.PrevView = UpdateViewChara3DModel
    VRFW_Outfit.PrevInitNoWindow = InitChara3DModelByUniformNoWindow
  end

  function UpdateViewChara3DModel(a1, ...)
    local item, u = VRFW_Outfit.Of(a1)
    if item == 0 or u == 0 then
      return VRFW_Outfit.PrevView(a1, ...)
    end
    return VRFW_Outfit.Dressed(u, VRFW_Outfit.PrevView, a1, ...)
  end

  function InitChara3DModelByUniformNoWindow(a1, ...)
    local item, u = VRFW_Outfit.Of(a1)
    if item == 0 or u == 0 then
      return VRFW_Outfit.PrevInitNoWindow(a1, ...)
    end
    return VRFW_Outfit.Dressed(u, VRFW_Outfit.PrevInitNoWindow, a1, ...)
  end
end
